using Hospital.Web.Data; using Hospital.Web.Models; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace Hospital.Web.Controllers; public class PatientsController(AppDbContext db):Controller { public async Task<IActionResult> Index(string? q){var x=db.Patients.AsQueryable(); if(!string.IsNullOrWhiteSpace(q)) x=x.Where(p=>p.FullName.Contains(q)||p.FileNumber.Contains(q)||(p.Phone!=null&&p.Phone.Contains(q))); return View(await x.OrderByDescending(p=>p.Id).ToListAsync());} public IActionResult Create()=>View(new Patient{FileNumber=$"P-{DateTime.Now:yyyyMMddHHmmss}"}); [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(Patient m){if(!ModelState.IsValid)return View(m);db.Add(m);await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}}
